// Handle both array and single object (HTTP node auto-splits)
const items = $input.all();
const invoices = [];
for (const item of items) {
  const json = item.json;
  if (Array.isArray(json)) {
    invoices.push(...json);
  } else {
    invoices.push(json);
  }
}
if (invoices.length === 0) return [];
return invoices.map(inv => ({ json: inv }));

const invoice = $input.first().json;
const ocrText = invoice.raw_ocr_text || '';
const vendor = invoice.vendor_name || 'Unknown';

const prompt = `You are an invoice categorization system. Given the following invoice OCR text, categorize the expense and provide a human-readable reasoning.

OCR Text:
---
${ocrText}
---

Return ONLY valid JSON with these fields:
{
  "category": "string — one of: Cloud Infrastructure, Software SaaS, Office Supplies, Travel, Professional Services, Marketing, Utilities, Hardware, Hosting, Communication, Other",
  "category_confidence": number between 0 and 1,
  "is_recurring": boolean,
  "reasoning": "string — 1-2 sentence explanation of why this category was chosen"
}

Rules:
- Choose the most specific category that fits.
- is_recurring = true if this looks like a subscription or repeating service.
- Return ONLY the JSON object, no markdown fences, no explanation.`;

return [{
  json: {
    invoiceId: invoice.id,
    vendor: invoice.vendor_name,
    total: invoice.total,
    flags: invoice.flags || [],
    prompt
  }
}];

const response = $input.first().json;
const prev = $('Build Categorization Prompt').first().json;

let text = '';
try {
  text = response.candidates[0].content.parts[0].text;
} catch (e) {
  throw new Error(`Gemini response unexpected: ${JSON.stringify(response)}`);
}

let cleaned = text.trim();
if (cleaned.startsWith('```')) {
  cleaned = cleaned.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '').trim();
}

let category;
try {
  category = JSON.parse(cleaned);
} catch (e) {
  throw new Error(`Failed to parse category JSON: ${cleaned.substring(0, 200)}`);
}

return [{
  json: {
    invoiceId: prev.invoiceId,
    vendor: prev.vendor,
    total: prev.total,
    existingFlags: prev.flags,
    category: category.category,
    category_confidence: category.category_confidence,
    is_recurring: category.is_recurring,
    reasoning: category.reasoning
  }
}];

const stats = $input.first().json;
const prev = $('Parse Category Response').first().json;

let anomalyNote = null;
const flags = [...(prev.existingFlags || [])];

const statsArray = Array.isArray(stats) ? stats : [stats];
const firstStat = statsArray.length > 0 ? statsArray[0] : null;

if (firstStat && firstStat.avg_monthly_amount_6mo) {
  const avg = firstStat.avg_monthly_amount_6mo;
  const current = prev.total || 0;
  const deviation = Math.abs(current - avg) / avg;

  if (deviation > 0.5) {
    const pct = Math.round(deviation * 100);
    const direction = current > avg ? 'above' : 'below';
    anomalyNote = `Amount is ${pct}% ${direction} the 6-month average of ${avg} for ${prev.vendor}`;
    if (!flags.includes('anomalous_amount')) {
      flags.push('anomalous_amount');
    }
  }
} else {
  anomalyNote = `No vendor history for ${prev.vendor} — first invoice from this vendor`;
}

return [{
  json: {
    invoiceId: prev.invoiceId,
    category: prev.category,
    category_confidence: prev.category_confidence,
    is_recurring: prev.is_recurring,
    reasoning: prev.reasoning,
    anomaly_note: anomalyNote,
    flags
  }
}];

const data = $input.first().json;

// If no flags were added and confidence is high, auto-approve
const hasFlags = data.flags && data.flags.length > 0;
const highConfidence = (data.category_confidence || 0) >= 0.8;
let status = 'processing';

if (!hasFlags && highConfidence) {
  status = 'auto_approved';
} else {
  status = 'flagged';
}

return [{
  json: {
    ...data,
    status
  }
}];

